package com.circlenet.domain.person.model;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="person_memories") public class PersonMemoryEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="owner_user_id",nullable=false)private Long ownerUserId;@Column(name="person_user_id",nullable=false)private Long personUserId;private String title;@Column(columnDefinition="TEXT")private String note;@Column(name="media_key")private String mediaKey;@Column(name="media_name")private String mediaName;@Column(name="media_type")private String mediaType;@Column(name="media_size")private Long mediaSize;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();
 public Long getId(){return id;}public Long getOwnerUserId(){return ownerUserId;}public void setOwnerUserId(Long v){ownerUserId=v;}public Long getPersonUserId(){return personUserId;}public void setPersonUserId(Long v){personUserId=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getNote(){return note;}public void setNote(String v){note=v;}public String getMediaKey(){return mediaKey;}public void setMediaKey(String v){mediaKey=v;}public String getMediaName(){return mediaName;}public void setMediaName(String v){mediaName=v;}public String getMediaType(){return mediaType;}public void setMediaType(String v){mediaType=v;}public Long getMediaSize(){return mediaSize;}public void setMediaSize(Long v){mediaSize=v;}public Instant getCreatedAt(){return createdAt;}
}
